<dialog id="route-choice-dialog" aria-labelledby="route-choice-title"><div class="dialog-heading"><h2 id="route-choice-title">Как идти в корпус И?</h2><button id="route-choice-close" type="button" class="icon-button" aria-label="Закрыть выбор пути">${ie("close")}</button></div><div id="route-choice-list" aria-label="Варианты маршрута"></div></dialog>
